function headers(){return session?.access_token?{"Authorization":"Bearer "+session.access_token}:{}}
async function api(path,opts={}){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),90000);let r;try{r=await fetch(base+path,{...opts,signal:controller.signal,headers:{...headers(),...(opts.headers||{})}})}catch(e){if(e.name==="AbortError")throw new Error("Request timed out after 90 seconds. Check Render availability and backend logs.");throw new Error("Could not reach the backend: "+e.message)}finally{clearTimeout(timeout)}const data=await r.json().catch(()=>({detail:r.statusText}));if(!r.ok)throw new Error(typeof data.detail==="string"?data.detail:JSON.stringify(data.detail||"Request failed ("+r.status+")"));return data}
function money(v){return v==null?"—":"₹"+Number(v).toLocaleString("en-IN",{maximumFractionDigits:4})}
function pct(v){return v==null?"—":(v*100).toFixed(2)+"%"}function ratio(v){return v==null?"—":Number(v).toFixed(2)}
function showError(e){$("banner").textContent=e.message;$("banner").classList.add("error")}
async function loadStatus(){try{const s=await api("/v1/nav/status");$("schemeCount").textContent=Number(s.scheme_master_count||0).toLocaleString("en-IN");const snap=s.latest_snapshot;$("lastRun").textContent=snap?new Date(snap.retrieved_at).toLocaleString():"Never";$("freshness").textContent=snap?(s.freshness_status+" · "+s.retrieval_age_hours+"h retrieval · "+s.effective_nav_status+" ("+s.effective_nav_age_days+"d NAV age)"):"No successful ingestion yet";$("coverage").textContent=snap?snap.min_nav_date+" → "+snap.max_nav_date:"—";$("quality").textContent=snap?snap.quality_status:"—";$("health").textContent="Database reachable · "+(snap?(s.freshness_status+" · "+s.effective_nav_status):"Connected; no successful NAV snapshot");if(!snap){$("banner").textContent="DATABASE CONNECTED · NAV NOT INITIALIZED. Your database is reachable, but there are no successful ingestion snapshots or scheme records yet. The daily AMFI ingestion is scheduled by the service. Once the first validated snapshot is committed, your scheme explorer and research metrics will populate automatically."}else{$("banner").textContent="INGESTION DATA FOUND · Snapshot "+snap.snapshot_id+" · "+snap.records_valid+" valid source rows · NAV effective date "+snap.max_nav_date+" · retrieved "+new Date(snap.retrieved_at).toLocaleString()}$("banner").classList.remove("error");return true}catch(e){showError(e);$("health").textContent="Backend or database unavailable · "+e.message;return false}}
let fundOffset=0;const FUND_PAGE_SIZE=30;let fundTotal=0;
