function syncDashboardCategoryTileSelection(){const selected=$("filterCategory").value;document.querySelectorAll("#dashboardCategoryTiles .dashboard-category-tile").forEach(tile=>tile.setAttribute("aria-pressed",String(tile.dataset.category===selected)))}
function renderDashboardCategoryTiles(categories){const host=$("dashboardCategoryTiles");if(!host)return;const values=[...new Set((categories||[]).map(value=>String(value||"").trim()).filter(Boolean))];if(!values.length){host.innerHTML='<div class="dashboard-category-loading muted">Verified scheme-group classifications are not available yet.</div>';return}host.innerHTML=values.map((value,index)=>'<button type="button" class="dashboard-category-tile" data-category="'+escapeHtml(value)+'" aria-pressed="'+($("filterCategory").value===value?"true":"false")+'"><span class="dashboard-category-index">'+String(index+1).padStart(2,"0")+'</span><strong>'+escapeHtml(value)+'</strong><small>Explore schemes</small></button>').join("");host.querySelectorAll(".dashboard-category-tile").forEach(button=>{button.addEventListener("click",()=>{const category=button.dataset.category;$("filterCategory").value=category;$("filterSubCategory").value="";fundOffset=0;syncDashboardCategoryTileSelection();setView("funds");loadSchemes(true).catch(showError)})})}
async function loadFundFacets(){try{const d=await api("/v1/nav/facets");const controls=[["filterAmc",d.amcs||[],"All AMCs"],["filterCategory",d.categories||[],"All scheme groups"],["filterSubCategory",d.sub_categories||[],"All sub-categories"],["filterAsset",d.asset_classes||[],"All asset classes"],["filterPlan",d.plan_types||[],"All plans"],["filterOption",d.option_types||[],"All options"]];for(const [id,values,label] of controls){const select=$(id),previous=select.value;select.innerHTML='<option value="">'+label+'</option>'+values.map(value=>'<option value="'+escapeHtml(value)+'">'+escapeHtml(value)+'</option>').join("");if(values.includes(previous))select.value=previous}renderDashboardCategoryTiles(d.categories||[])}catch(e){showError(e)}}
async function loadSchemes(resetPage=false){try{if(resetPage)fundOffset=0;const params=new URLSearchParams({limit:String(FUND_PAGE_SIZE),offset:String(fundOffset)});const q=$("search").value.trim();if(q)params.set("q",q);for(const [key,value] of Object.entries(selectedFundFilters()))if(value)params.set(key,value);const d=await api("/v1/nav/schemes?"+params.toString());fundTotal=d.total_matching||0;$("schemeRows").innerHTML=d.items.map(x=>'<tr><td><strong>'+escapeHtml(x.scheme_name)+'</strong><div class="muted">'+escapeHtml(x.amc||"AMC not classified")+' · '+escapeHtml(x.category_group||"Scheme group unavailable")+(x.category?' · '+escapeHtml(x.category):'')+'</div></td><td>'+x.scheme_code+'</td><td>'+money(x.latest_nav)+'</td><td>'+(x.nav_date||"—")+'</td><td><button class="schemeDetails" data-code="'+x.scheme_code+'">Research</button></td></tr>').join("")||(fundTotal===0?'<tr><td colspan="5">No matching schemes. Try clearing one or more filters.</td></tr>':'<tr><td colspan="5">No schemes on this page.</td></tr>');const first=fundTotal?fundOffset+1:0,last=Math.min(fundOffset+d.items.length,fundTotal);$("fundResultCount").textContent=fundTotal.toLocaleString("en-IN")+" matching schemes · showing "+first+"–"+last;$("fundPageLabel").textContent="Page "+(Math.floor(fundOffset/FUND_PAGE_SIZE)+1)+" of "+Math.max(1,Math.ceil(fundTotal/FUND_PAGE_SIZE));$("fundPrev").disabled=fundOffset===0;$("fundNext").disabled=fundOffset+FUND_PAGE_SIZE>=fundTotal;document.querySelectorAll(".schemeDetails").forEach(b=>b.onclick=()=>loadSchemeDetail(b.dataset.code));return true}catch(e){showError(e);return false}}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
async function refresh(){try{throw new Error("NAV refresh is managed by the scheduled service. Personal accounts cannot trigger ingestion.");$("refresh").disabled=true;$("refresh").textContent="Fetching AMFI…";$("banner").classList.remove("error");$("banner").textContent="Request sent. Fetching the official AMFI feed, validating rows and committing the database transaction…";const r=await api("/v1/nav/refresh",{method:"POST"});if(r.status!=="ingested"||!r.snapshot||!r.snapshot.snapshot_id)throw new Error("Backend did not return a committed ingestion snapshot. Treat this refresh as failed.");$("refresh").textContent="Updating dashboard…";const details="Inserted "+(r.nav_rows_inserted??r.nav_rows_upserted??0)+" · corrected "+(r.nav_rows_updated??0)+" · unchanged "+(r.nav_rows_unchanged??0)+" NAV rows. Quality: "+r.snapshot.quality_status+". Effective NAV date: "+r.snapshot.max_nav_date+". Snapshot #"+r.snapshot.snapshot_id+".";const statusOk=await loadStatus();const schemesOk=await loadSchemes();$("banner").textContent=statusOk&&schemesOk?"REFRESH COMMITTED · "+details:"REFRESH COMMITTED, BUT DASHBOARD RELOAD FAILED · "+details+" Use Refresh data or reload the page.";if(!statusOk||!schemesOk)$("banner").classList.add("error")}catch(e){showError(e)}finally{$("refresh").disabled=false;$("refresh").textContent="↻ Refresh NAV"}}
async function analyze(){try{const code=$("schemeCode").value.trim();if(!/^\d+$/.test(code))throw new Error("Enter a valid scheme code.");const d=await api("/v1/analytics/performance/"+code);if(d.metrics.status!=="OK"){$("performance").textContent="Insufficient history for analysis.";return}const m=d.metrics;$("performance").innerHTML='<div class="grid" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div><div class="muted">CAGR</div><h2>'+pct(m.cagr)+'</h2></div><div><div class="muted">Total return</div><h2>'+pct(m.total_return)+'</h2></div><div><div class="muted">Annualised volatility</div><h2>'+pct(m.annualized_volatility)+'</h2></div><div><div class="muted">Maximum drawdown</div><h2 class="negative">'+pct(m.max_drawdown)+'</h2></div><div><div class="muted">Sharpe ratio</div><h2>'+ratio(m.sharpe_ratio)+'</h2></div><div><div class="muted">Sortino ratio</div><h2>'+ratio(m.sortino_ratio)+'</h2></div></div><p class="muted">Period: '+m.start_date+' to '+m.end_date+' · '+m.observations+' observations · risk-free assumption '+pct(m.risk_free_rate_assumption)+'</p>'}catch(e){showError(e)}}
function renderNavChart(series){const panel=$("schemeChartPanel"),host=$("schemeNavChart");if(!Array.isArray(series)||series.length<2){panel.classList.add("hidden");host.innerHTML='<div class="muted">Not enough historical observations to draw a NAV chart.</div>';return}const width=900,height=250,pad={left:58,right:18,top:18,bottom:32},values=series.map(x=>Number(x.nav)).filter(Number.isFinite);if(values.length<2){panel.classList.add("hidden");return}const min=Math.min(...values),max=Math.max(...values),range=max-min||Math.max(max*.02,1);const points=series.map((item,index)=>{const value=Number(item.nav),x=pad.left+(index/(series.length-1))*(width-pad.left-pad.right),y=pad.top+(1-(value-min)/range)*(height-pad.top-pad.bottom);return {x,y,value,date:item.date}});const path=points.map((p,i)=>(i?"L":"M")+p.x.toFixed(2)+","+p.y.toFixed(2)).join(" ");const area=path+" L"+points[points.length-1].x+","+((height-pad.bottom))+" L"+points[0].x+","+((height-pad.bottom))+" Z";const grid=[0,1,2,3].map(i=>{const y=pad.top+i*(height-pad.top-pad.bottom)/3,value=max-i*range/3;return '<line x1="'+pad.left+'" y1="'+y+'" x2="'+(width-pad.right)+'" y2="'+y+'" stroke="#e8edf3" stroke-dasharray="4 5"/><text x="'+(pad.left-10)+'" y="'+(y+4)+'" text-anchor="end" fill="#77818d" font-size="11">'+value.toFixed(2)+'</text>'}).join("");host.innerHTML='<svg viewBox="0 0 '+width+' '+height+'" role="img" aria-label="Mutual fund NAV history from '+escapeHtml(series[0].date)+' to '+escapeHtml(series[series.length-1].date)+'"><defs><linearGradient id="navFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#4e86ce" stop-opacity=".22"/><stop offset="100%" stop-color="#4e86ce" stop-opacity="0"/></linearGradient></defs>'+grid+'<path d="'+area+'" fill="url(#navFill)"/><path d="'+path+'" fill="none" stroke="#326fc8" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/><circle cx="'+points[points.length-1].x+'" cy="'+points[points.length-1].y+'" r="4.5" fill="#326fc8" stroke="white" stroke-width="2"/><text x="'+pad.left+'" y="'+(height-7)+'" fill="#77818d" font-size="11">'+escapeHtml(series[0].date)+'</text><text x="'+(width-pad.right)+'" y="'+(height-7)+'" text-anchor="end" fill="#77818d" font-size="11">'+escapeHtml(series[series.length-1].date)+'</text></svg>';$("schemeChartRange").textContent=series.length.toLocaleString("en-IN")+" observations · "+series[0].date+" to "+series[series.length-1].date;panel.classList.remove("hidden")}
async function loadSchemeDetail(code){try{const d=await api("/v1/nav/schemes/"+encodeURIComponent(code));const m=d.performance||{};$("schemeDetailPanel").classList.remove("hidden");$("schemeDetailContent").innerHTML='<div class="sectionhead"><div><strong>'+escapeHtml(d.scheme_name)+'</strong><div class="muted">'+escapeHtml(d.amc||"AMC not classified")+' · '+escapeHtml(d.category_group||"Scheme group unavailable")+(d.category?' · '+escapeHtml(d.category):'')+' · '+escapeHtml(d.plan_type||"Plan not classified")+' · '+escapeHtml(d.option_type||"Option not classified")+'</div></div><span class="pill">Scheme '+d.scheme_code+'</span></div><div class="grid" style="grid-template-columns:repeat(3,minmax(0,1fr));margin-top:14px"><div><div class="muted">Latest NAV</div><strong>'+money(d.latest_nav)+'</strong><div class="muted">'+escapeHtml(d.latest_nav_date||"—")+'</div></div><div><div class="muted">CAGR</div><strong>'+pct(m.cagr)+'</strong></div><div><div class="muted">Total return</div><strong>'+pct(m.total_return)+'</strong></div><div><div class="muted">Volatility</div><strong>'+pct(m.annualized_volatility)+'</strong></div><div><div class="muted">Max drawdown</div><strong class="negative">'+pct(m.max_drawdown)+'</strong></div><div><div class="muted">Observations</div><strong>'+Number(d.observations_in_window||0).toLocaleString("en-IN")+'</strong></div></div><p class="muted">Growth ISIN: '+escapeHtml(d.isin_growth||"—")+' · IDCW reinvestment ISIN: '+escapeHtml(d.isin_dividend_reinvestment||"—")+'</p><p class="muted">Coverage: '+escapeHtml(d.window_start||"—")+' → '+escapeHtml(d.window_end||"—")+'. Metrics are NAV-derived and do not include benchmark TRI or distributions unless reflected in the NAV series.</p>' ;renderNavChart(d.nav_series||[]);$("schemeDetailPanel").scrollIntoView({behavior:"smooth",block:"nearest"})}catch(e){showError(e)}}
async function compareFunds(){try{const codes=$("compareCodes").value.split(",").map(x=>x.trim()).filter(Boolean);if(codes.length<2||codes.length>10||codes.some(x=>!/^\d+$/.test(x)))throw new Error("Enter 2–10 valid numeric scheme codes separated by commas.");const d=await api("/v1/analytics/compare",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({scheme_codes:codes.map(Number),days:Number($("compareDays").value)})});$("compareResult").innerHTML='<div class="tablewrap"><table><thead><tr><th>SCHEME</th><th>NAV DATE</th><th>OBSERVATIONS</th><th>TOTAL RETURN</th><th>CAGR</th><th>VOLATILITY</th><th>MAX DRAWDOWN</th></tr></thead><tbody>'+d.results.map(x=>'<tr><td>'+escapeHtml(x.scheme_name)+' ('+x.scheme_code+')</td><td>'+(x.latest_nav_date||"—")+'</td><td>'+x.observations+'</td><td>'+pct(x.metrics.total_return)+'</td><td>'+pct(x.metrics.cagr)+'</td><td>'+pct(x.metrics.annualized_volatility)+'</td><td>'+pct(x.metrics.max_drawdown)+'</td></tr>').join("")+'</tbody></table></div><p class="muted">'+escapeHtml(d.methodology)+'</p>'}catch(e){showError(e)}}
