async function loadPortfolioCommandCentre(portfolios){
 const cards=$("ccPortfolioCards"),coverage=$("ccValuationCoverage");
 if(!portfolios.length){
  $("commandCentreStatus").textContent="No portfolios yet";$("ccMarketValue").textContent="₹0";$("ccCostBasis").textContent="₹0";$("ccUnrealized").textContent="—";$("ccPortfolioCount").textContent="0";
  coverage.textContent="No portfolio valuations exist yet. Create a portfolio and add holdings to begin.";
  cards.innerHTML='<div class="command-empty"><strong>Your investment workspace is ready.</strong><p>Create your first portfolio in Portfolio Lab, then add transactions or import a statement to unlock valuation, returns and risk insights.</p><button type="button" class="primary" id="ccCreateFirst">Create your first portfolio</button></div>';
  $("ccCreateFirst").onclick=()=>setView("portfolio");return;
 }
 const results=await Promise.allSettled(portfolios.map(async p=>({portfolio:p,valuation:await api("/v1/portfolios/"+p.id+"/valuation")})));
 const valid=results.filter(x=>x.status==="fulfilled").map(x=>x.value),failed=results.filter(x=>x.status==="rejected").length;
 const pricedValue=valid.reduce((sum,x)=>sum+Number(x.valuation.current_value||0),0),loadedCost=valid.reduce((sum,x)=>sum+Number(x.valuation.remaining_cost_basis||0),0);
 const fullyValued=valid.filter(x=>x.valuation.unrealized_gain_loss!=null&&!x.valuation.missing_nav_scheme_codes?.length&&!x.valuation.stale_nav_scheme_codes?.length);
 const allComplete=failed===0&&valid.length===portfolios.length&&fullyValued.length===portfolios.length;
 const completeGain=allComplete?fullyValued.reduce((sum,x)=>sum+Number(x.valuation.unrealized_gain_loss),0):null;
 $("ccMarketValue").textContent=money(pricedValue);$("ccCostBasis").textContent=money(loadedCost);$("ccUnrealized").textContent=completeGain==null?"—":money(completeGain);
 $("ccPortfolioCount").textContent=portfolios.length.toLocaleString("en-IN");
 $("commandCentreStatus").textContent=allComplete?"All portfolios fully valued":"Partial valuation · "+valid.length+"/"+portfolios.length+" loaded";
 const missingNavCount=valid.reduce((sum,x)=>sum+(x.valuation.missing_nav_scheme_codes?.length||0),0),staleNavCount=valid.reduce((sum,x)=>sum+(x.valuation.stale_nav_scheme_codes?.length||0),0);
 coverage.textContent="Known priced value includes "+valid.length+" of "+portfolios.length+" portfolios. "+(failed?failed+" portfolio valuation(s) failed to load. ":"")+(missingNavCount?missingNavCount+" holding(s) have missing NAV. ":"")+(staleNavCount?staleNavCount+" holding(s) have stale NAV. ":"")+(allComplete?"All portfolios have complete, fresh valuation coverage.":"Aggregate unrealized gain/loss is withheld until every portfolio is complete and fresh.");
 cards.innerHTML=valid.map(({portfolio:p,valuation:v})=>{
  const incomplete=!!(v.missing_nav_scheme_codes?.length||v.stale_nav_scheme_codes?.length||v.unrealized_gain_loss==null);
  return '<article class="command-card"><div class="command-card-head"><div><strong>'+escapeHtml(p.name)+'</strong><span>Portfolio #'+p.id+'</span></div><button type="button" class="command-open" data-portfolio="'+p.id+'">Open →</button></div><div class="command-value">'+money(v.current_value)+'</div><div class="command-stats"><div><span>Cost basis</span><strong>'+money(v.remaining_cost_basis)+'</strong></div><div><span>Unrealized P/L</span><strong class="'+(incomplete?"":v.unrealized_gain_loss>=0?"positive":"negative")+'">'+(incomplete?"—":money(v.unrealized_gain_loss))+'</strong></div><div><span>XIRR</span><strong>'+(incomplete?"—":pct(v.xirr))+'</strong></div></div><div class="command-foot">'+(incomplete?"Known priced value · ":"Fully valued · ")+escapeHtml(v.valuation_freshness||"UNKNOWN")+' · '+escapeHtml(v.valuation_date||"No NAV date")+(v.missing_nav_scheme_codes?.length?' · '+v.missing_nav_scheme_codes.length+' missing NAV':'')+(v.stale_nav_scheme_codes?.length?' · '+v.stale_nav_scheme_codes.length+' stale NAV':'')+'</div></article>';
 }).join("")+(failed?'<div class="notice">Could not load '+failed+' portfolio valuation(s). Retry from Portfolio Lab; unavailable values are excluded from the known-priced subtotal.</div>':"")||'<div class="muted">No portfolios are available.</div>';
 document.querySelectorAll(".command-open").forEach(button=>button.onclick=()=>{setView("portfolio");$("portfolioId").value=button.dataset.portfolio;$("portfolioSelect").value=button.dataset.portfolio;loadPortfolio()});
}
async function loadPortfolios(){try{const d=await api("/v1/portfolios");const selected=$("portfolioId").value.trim();$("portfolioSelect").innerHTML='<option value="">Select a saved portfolio…</option>'+d.items.map(p=>'<option value="'+p.id+'">'+escapeHtml(p.name)+' (#'+p.id+')</option>').join("");$("goalPortfolio").innerHTML='<option value="">Use manually entered current amount</option>'+d.items.map(p=>'<option value="'+p.id+'">'+escapeHtml(p.name)+' (#'+p.id+')</option>').join("");if(selected)$("portfolioSelect").value=selected;await loadPortfolioCommandCentre(d.items)}catch(e){showError(e);$("commandCentreStatus").textContent="Could not load portfolios";$("ccPortfolioCards").textContent=e.message}}
function portfolioId(){const id=$("portfolioId").value.trim();if(!/^\d+$/.test(id))throw new Error("Enter a valid portfolio ID.");return id}
