async function loadPortfolioLookthrough(){const id=portfolioId(),requestId=portfolioViewRequest;const d=await api("/v1/portfolios/"+id+"/lookthrough?max_disclosure_age_days="+$("lookthroughAgeDays").value);if(requestId!==portfolioViewRequest||id!==portfolioId())return null;const coverage=d.coverage||{};$("lookthroughCoverage").textContent="Coverage: "+coverage.status+" · Fresh covered value "+money(coverage.fresh_covered_market_value)+" ("+(coverage.fresh_covered_weight_pct==null?"unavailable":Number(coverage.fresh_covered_weight_pct).toFixed(2)+"%")+") · Stale covered value "+money(coverage.stale_covered_market_value)+" · Missing NAV: "+(coverage.missing_nav_scheme_codes||[]).join(", ")+" · Missing disclosures: "+(coverage.missing_disclosure_scheme_codes||[]).join(", ")+" · Stale NAV: "+(coverage.stale_nav_scheme_codes||[]).join(", ")+" · Stale disclosures: "+(coverage.stale_disclosure_scheme_codes||[]).join(", ");const concentration=d.security_concentration||{};const showPct=value=>value==null?"—":Number(value).toFixed(2)+"%";const concentrationPanel='<div class="panel"><h3>Security concentration · observed disclosures only</h3><div class="stats">'+[[ "Top 1",showPct(concentration.top_1_weight_of_observed_positive_pct) ],[ "Top 5",showPct(concentration.top_5_weight_of_observed_positive_pct) ],[ "Top 10",showPct(concentration.top_10_weight_of_observed_positive_pct) ],[ "HHI",concentration.hhi_points==null?"—":Number(concentration.hhi_points).toFixed(2) ],[ "Effective securities",concentration.effective_security_count==null?"—":Number(concentration.effective_security_count).toFixed(2) ],[ "ISIN identity coverage",showPct(concentration.isin_identity_coverage_pct) ]].map(item=>'<div class="stat"><label>'+item[0]+'</label><strong>'+item[1]+'</strong></div>').join("")+'</div><p class="muted">Positive disclosed exposure '+money(concentration.positive_disclosed_exposure_inr)+' · Negative exposure '+money(concentration.negative_disclosed_exposure_inr)+' · Fresh positive exposure '+money(concentration.fresh_positive_disclosed_exposure_inr)+' · Stale positive exposure '+money(concentration.stale_positive_disclosed_exposure_inr)+'</p><p class="footnote">'+escapeHtml(concentration.interpretation||"Concentration uses observed verified disclosures only.")+'</p></div>';const securities=(d.top_securities||[]).map(item=>'<tr><td>'+escapeHtml(item.security_name)+'</td><td>'+escapeHtml(item.security_id)+'</td><td>'+escapeHtml(item.identity_basis|| (item.is_isin?"ISIN":"Disclosure-local name"))+'</td><td>'+escapeHtml(item.sector||"Unclassified")+'</td><td>'+money(item.lookthrough_value)+'</td><td>'+money(item.fresh_disclosure_exposure_inr)+'</td><td>'+money(item.stale_disclosure_exposure_inr)+'</td><td>'+(item.portfolio_weight_pct==null?"—":Number(item.portfolio_weight_pct).toFixed(2)+"%")+'</td><td>'+item.scheme_count+'</td></tr>').join("")||'<tr><td colspan="9" class="muted">No verified look-through holdings found.</td></tr>';const sectors=(d.sector_exposure||[]).map(item=>'<tr><td>'+escapeHtml(item.sector)+'</td><td>'+money(item.lookthrough_value)+'</td><td>'+(item.portfolio_weight_pct==null?"—":Number(item.portfolio_weight_pct).toFixed(2)+"%")+'</td></tr>').join("")||'<tr><td colspan="3" class="muted">No verified sector exposure found.</td></tr>';$("lookthroughSecurities").innerHTML=concentrationPanel+'<div class="panel"><h3>Top underlying securities</h3><div class="tablewrap"><table><thead><tr><th>Security</th><th>Security ID</th><th>Identity basis</th><th>Sector</th><th>Total exposure</th><th>Fresh exposure</th><th>Stale exposure</th><th>Portfolio weight</th><th>Funds</th></tr></thead><tbody>'+securities+'</tbody></table></div></div><div class="panel"><h3>Sector exposure</h3><div class="tablewrap"><table><thead><tr><th>Sector</th><th>Look-through value</th><th>Portfolio weight</th></tr></thead><tbody>'+sectors+'</tbody></table></div></div><div class="panel"><h3>Source disclosures</h3>'+(d.sources||[]).map(source=>'<div class="muted"><a href="'+escapeHtml(source.source_document_url)+'" target="_blank" rel="noopener noreferrer">'+escapeHtml(source.scheme_name)+'</a> · '+escapeHtml(source.as_of_date)+' · '+escapeHtml(source.freshness)+' · SHA-256 '+escapeHtml(source.source_sha256)+'</div>').join("")+'</div><p class="footnote">'+escapeHtml(d.methodology)+' '+(d.limitations||[]).map(escapeHtml).join(" ")+'</p>';return d}
async function loadPortfolioRisk(){
 const id=portfolioId(),requestId=portfolioViewRequest;lastPortfolioRisk=null;lastPortfolioRiskPortfolioId=null;
 $("portfolioStressInputs").innerHTML='<div class="muted">Loading fresh risk data. Previous scenario inputs are cleared.</div>';
 $("portfolioRiskStatus").textContent="Calculating…";$("portfolioRiskResult").textContent="Loading stored NAV observations for this portfolio…";
 const d=await api("/v1/portfolios/"+id+"/risk?days="+$("portfolioRiskDays").value);
 if(requestId!==portfolioViewRequest||id!==portfolioId())return null;
 if(!d.metrics||d.metrics.status!=="OK"||d.status==="STALE_NAV"){
  $("portfolioRiskStatus").textContent=d.status||"Unavailable";
  $("portfolioRiskResult").textContent=d.note||("Risk metrics unavailable or stale: "+(d.status||"insufficient data"));
  $("portfolioStressInputs").innerHTML='<div class="muted">Per-scheme shocks are disabled until fresh, comparable risk data is available.</div>';
  return d;
 }
 lastPortfolioRisk=d;lastPortfolioRiskPortfolioId=id;
 const m=d.metrics;
 const metrics=[["Annualised volatility",pct(m.annualized_volatility)],["Historical VaR 95%",pct(m.historical_var_95)],["Historical CVaR 95%",pct(m.historical_cvar_95)],["Maximum drawdown",pct(m.max_drawdown)],["Worst 1 day",pct(m.worst_1d_return)],["Worst 5 days",pct(m.worst_5d_return)],["Worst 21 days",pct(m.worst_21d_return)],["Sharpe ratio",m.sharpe_ratio==null?"—":Number(m.sharpe_ratio).toFixed(2)]];
 $("portfolioRiskStatus").textContent=d.status||"OK";
 await renderStressInputs();
 if(requestId!==portfolioViewRequest||id!==portfolioId())return null;
 $("portfolioRiskResult").innerHTML='<div class="stats">'+metrics.map(item=>'<div class="stat"><label>'+item[0]+'</label><strong>'+item[1]+'</strong></div>').join("")+'</div><p class="muted">Lookback '+d.lookback_days+' days · '+m.daily_return_observations+' paired returns · '+escapeHtml(m.start_date||"—")+' to '+escapeHtml(m.end_date||"—")+'. '+escapeHtml(m.methodology||"")+'</p>'+(d.status==="STALE_NAV"?'<div class="notice error">Stale NAV detected for scheme(s): '+(d.stale_nav_scheme_codes||[]).join(", ")+'. Treat this risk estimate as stale.</div>':"");
 return d;
}
async function loadPortfolioReports(){const id=portfolioId(),requestId=portfolioViewRequest;const d=await api("/v1/portfolios/"+id+"/reports");if(requestId!==portfolioViewRequest||id!==portfolioId())return null;const items=d.items||[];$("portfolioReportCount").textContent=items.length+" saved";$("portfolioReportHistory").innerHTML=items.map(item=>'<div class="command-centre-card"><div><strong>Report #'+item.report_id+'</strong><div class="muted">Generated '+escapeHtml(item.generated_at)+' · NAV through '+escapeHtml(item.source_max_nav_date||"unknown")+'</div><div class="muted">SHA-256 '+escapeHtml(item.content_sha256)+'</div></div><div class="toolbar"><button type="button" data-report-download="'+item.report_id+'">Download PDF</button><button type="button" data-report-verify="'+item.report_id+'">Verify snapshot</button></div></div>').join("")||'<div class="muted">No saved reports for this portfolio yet.</div>';document.querySelectorAll("[data-report-download]").forEach(button=>button.onclick=()=>downloadPortfolioReport(Number(button.dataset.reportDownload)).catch(error=>{$("portfolioReportResult").textContent=error.message}));document.querySelectorAll("[data-report-verify]").forEach(button=>button.onclick=()=>verifyPortfolioReport(Number(button.dataset.reportVerify)).catch(error=>{$("portfolioReportResult").textContent=error.message}));return d}
async function downloadPortfolioReport(id){const response=await fetch(base+"/v1/reports/"+id+"/pdf",{headers:headers()});if(!response.ok){const error=await response.json().catch(()=>({detail:response.statusText}));throw new Error(error.detail||"PDF export failed.")}const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement("a");link.href=url;link.download="portfolio-report-"+id+".pdf";document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);$("portfolioReportResult").textContent="PDF download started for report #"+id+"."}
async function verifyPortfolioReport(id){const d=await api("/v1/reports/"+id);const verified=d.integrity_status==="VERIFIED";$("portfolioReportResult").textContent="Report #"+id+" integrity: "+d.integrity_status+" · SHA-256 "+d.content_sha256+(verified?". Stored snapshot hash matches the saved report content.":" Hash mismatch detected; do not rely on this snapshot.");$("portfolioReportResult").className=verified?"result notice":"result notice error"}
async function generatePortfolioReport(){const button=$("generatePortfolioReport");button.disabled=true;button.textContent="Generating…";$("portfolioReportResult").textContent="Calculating valuation, historical risk, FIFO lots and source provenance…";try{const saved=await api("/v1/portfolios/"+portfolioId()+"/reports?days="+$("portfolioRiskDays").value,{method:"POST"});const response=await fetch(base+"/v1/reports/"+saved.report_id+"/pdf",{headers:headers()});if(!response.ok){const error=await response.json().catch(()=>({detail:response.statusText}));throw new Error(error.detail||"PDF export failed.")}await downloadPortfolioReport(saved.report_id);$("portfolioReportResult").textContent="Report #"+saved.report_id+" saved · SHA-256 "+saved.content_sha256+" · source NAV through "+(saved.source_max_nav_date||"not available")+". PDF download started.";await loadPortfolioReports()}finally{button.disabled=false;button.textContent="Generate PDF report"}}
async function loadTaxLots(){const id=portfolioId(),requestId=portfolioViewRequest;const d=await api("/v1/portfolios/"+id+"/tax-lots");if(requestId!==portfolioViewRequest||id!==portfolioId())return null;const realized=(d.realized_lots||[]).map(item=>'<tr><td>'+escapeHtml(item.buy_date)+'</td><td>'+escapeHtml(item.sell_date)+'</td><td>'+escapeHtml(item.units)+'</td><td>'+money(item.cost_basis)+'</td><td>'+money(item.net_proceeds)+'</td><td class="'+(Number(item.realized_gain_loss)>=0?"positive":"negative")+'">'+money(item.realized_gain_loss)+'</td><td>'+item.holding_period_days+'</td></tr>').join("")||'<tr><td colspan="7" class="muted">No realized FIFO lots.</td></tr>';const open=(d.open_lots||[]).map(item=>'<tr><td>'+escapeHtml(item.buy_date)+'</td><td>'+escapeHtml(item.scheme_code)+'</td><td>'+escapeHtml(item.units)+'</td><td>'+money(item.cost_basis)+'</td><td>'+money(item.latest_nav)+'</td><td>'+money(item.market_value)+'</td><td>'+money(item.unrealized_gain_loss)+'</td></tr>').join("")||'<tr><td colspan="7" class="muted">No open FIFO lots.</td></tr>';$("taxLotsResult").innerHTML='<div class="stats"><div class="stat"><label>Realized FIFO gain / loss</label><strong>'+money(d.realized_gain_loss)+'</strong></div><div class="stat"><label>Unrealized FIFO gain / loss</label><strong>'+money(d.unrealized_gain_loss)+'</strong></div><div class="stat"><label>Realized lots</label><strong>'+d.realized_lot_count+'</strong></div><div class="stat"><label>Open lots</label><strong>'+d.open_lot_count+'</strong></div></div><div class="panel"><h3>Realized redemptions · FIFO</h3><div class="tablewrap"><table><thead><tr><th>Buy date</th><th>Sell date</th><th>Units</th><th>Cost basis</th><th>Net proceeds</th><th>Gain / loss</th><th>Holding days</th></tr></thead><tbody>'+realized+'</tbody></table></div></div><div class="panel"><h3>Open acquisition lots</h3><div class="tablewrap"><table><thead><tr><th>Buy date</th><th>Scheme</th><th>Units</th><th>Cost basis</th><th>Latest NAV</th><th>Market value</th><th>Unrealized gain / loss</th></tr></thead><tbody>'+open+'</tbody></table></div></div><div class="notice">'+escapeHtml(d.tax_note)+' No tax liability is shown.</div>';return d}
async function renderStressInputs(){
 const host=$("portfolioStressInputs");
 if(!lastPortfolioRisk?.holdings?.length||lastPortfolioRiskPortfolioId!==portfolioId()){host.innerHTML='<div class="muted">Calculate fresh portfolio risk to load individual scheme shocks.</div>';return}
 const defaultShock=Number($("stressShockPct").value);
 host.innerHTML='<div class="stress-input-head"><strong>Per-scheme shock assumptions</strong><span>'+lastPortfolioRisk.holdings.length+' holdings · editable independently</span></div><div class="tablewrap"><table class="stress-input-table"><thead><tr><th>Fund</th><th>Scheme code</th><th>Current weight</th><th>Shock (%)</th></tr></thead><tbody>'+lastPortfolioRisk.holdings.map(item=>'<tr><td>'+escapeHtml(item.scheme_name||("Scheme "+item.scheme_code))+'</td><td>'+escapeHtml(item.scheme_code)+'</td><td>'+(item.portfolio_weight_pct==null?"—":Number(item.portfolio_weight_pct).toFixed(2)+"%")+'</td><td><input class="stress-scheme-shock" data-scheme-code="'+escapeHtml(item.scheme_code)+'" type="number" min="-100" max="100" step="0.5" value="'+(Number.isFinite(defaultShock)?defaultShock:-10)+'" aria-label="Shock percentage for '+escapeHtml(item.scheme_name||("scheme "+item.scheme_code))+'"></td></tr>').join("")+'</tbody></table></div><p class="footnote">These are user-defined sensitivity assumptions, not forecasts. A shock is applied to each scheme NAV exposure; the service returns the resulting portfolio sensitivity.</p>';
}
async function runPortfolioStress(){
 if(!lastPortfolioRisk?.holdings?.length||lastPortfolioRiskPortfolioId!==portfolioId())throw new Error("Calculate risk for the currently selected portfolio first; previous portfolio risk cannot be reused.");
 const name=$("stressScenarioName").value.trim();if(name.length<2)throw new Error("Enter a scenario name.");
 const controls=[...document.querySelectorAll(".stress-scheme-shock")];
 if(controls.length!==lastPortfolioRisk.holdings.length)throw new Error("Refresh portfolio risk to rebuild the per-scheme shock inputs.");
 const shocks=controls.map(control=>{const shock=Number(control.value);if(!Number.isFinite(shock)||shock< -100||shock>100)throw new Error("Every scheme shock must be between -100% and +100%.");return {scheme_code:Number(control.dataset.schemeCode),shock_pct:String(shock)}});
 const payload={scenario_name:name,shocks};
 const d=await api("/v1/portfolios/"+portfolioId()+"/stress",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});
 $("portfolioStressResult").textContent=d.scenario_name+" · Base value "+money(d.base_portfolio_value)+" · Estimated impact "+money(d.estimated_portfolio_impact)+" · Stressed value "+money(d.stressed_portfolio_value)+". "+d.scenario_type+(d.stale_nav_scheme_codes?.length?" · Stale NAV: "+d.stale_nav_scheme_codes.join(", "):"");
 return d;
}
let portfolioViewRequest=0;
async function loadPortfolio(){
 const requestId=++portfolioViewRequest,id=portfolioId();
 lastPortfolioRisk=null;lastPortfolioRiskPortfolioId=null;
 $("portfolioValuationDate").textContent="Loading valuation…";$("portfolioValuationStatus").textContent="Fetching current holdings and checking NAV freshness…";
 ["portfolioCurrentValue","portfolioCostBasis","portfolioRealized","portfolioUnrealized","portfolioTotalGain","portfolioXirr"].forEach(key=>$(key).textContent="—");
 $("holdingCount").textContent="Loading…";$("holdingRows").innerHTML='<tr><td colspan="8" class="muted">Loading holdings…</td></tr>';$("transactionCount").textContent="Loading…";$("transactionRows").innerHTML='<tr><td colspan="9" class="muted">Loading transaction history…</td></tr>';
 $("allocationCoverage").textContent="Loading…";$("allocationBreakdown").innerHTML='<div class="muted">Loading priced holdings…</div>';$("lookthroughSecurities").textContent="Loading verified underlying exposures…";
 $("portfolioRiskStatus").textContent="Not calculated";$("portfolioRiskResult").textContent="Risk will be calculated for this portfolio after valuation loads.";
 $("portfolioStressResult").textContent="Calculate risk for this portfolio before applying a stress scenario.";
 $("portfolioStressInputs").innerHTML='<div class="muted">Loading fresh portfolio holdings before enabling scenario inputs…</div>';
 $("portfolioReportHistory").innerHTML='<div class="muted">Loading saved reports…</div>';
 $("lookthroughCoverage").textContent="Loading verified disclosure coverage…";
 $("holdingRows").innerHTML='<tr><td colspan="8" class="muted">Loading holdings…</td></tr>';
 let d;try{d=await api("/v1/portfolios/"+id+"/valuation")}catch(error){if(requestId!==portfolioViewRequest||id!==portfolioId())return null;$("portfolioValuationDate").textContent="Valuation unavailable";$("portfolioValuationStatus").textContent="Valuation unavailable: "+error.message;$("holdingCount").textContent="Unavailable";$("holdingRows").innerHTML='<tr><td colspan="8" class="muted">Portfolio valuation could not be loaded. Retry after checking backend availability.</td></tr>';throw error}
 if(requestId!==portfolioViewRequest||id!==portfolioId())return null;
 $("portfolioCurrentValue").textContent=money(d.current_value);$("portfolioCostBasis").textContent=money(d.remaining_cost_basis);
 $("portfolioRealized").textContent=money(d.realized_gain_loss);$("portfolioUnrealized").textContent=money(d.unrealized_gain_loss);
 $("portfolioTotalGain").textContent=money(d.total_gain_loss);$("portfolioXirr").textContent=d.xirr==null?"—":pct(d.xirr);
 $("portfolioValuationDate").textContent=d.valuation_date?"As of "+d.valuation_date:"No NAV date";
 $("holdingCount").textContent=d.holdings.length+" holdings";
 $("portfolioValuationStatus").textContent=d.valuation_status+" · "+d.valuation_freshness+" · "+(d.valuation_note||"")+(d.missing_nav_scheme_codes?.length?" Missing NAV: "+d.missing_nav_scheme_codes.join(", ")+".":"")+(d.stale_nav_scheme_codes?.length?" Stale NAV: "+d.stale_nav_scheme_codes.join(", ")+".":"")+(d.xirr==null?" XIRR is unavailable until valuation data is complete and fresh.":"");
 $("holdingRows").innerHTML=d.holdings.map(h=>{const pnl=h.market_value==null?null:Math.round((Number(h.market_value)-Number(h.cost_basis)+Number.EPSILON)*100)/100;return '<tr><td>'+escapeHtml(h.scheme_name)+'<div class="muted">Code '+h.scheme_code+'</div></td><td>'+Number(h.units).toLocaleString("en-IN",{maximumFractionDigits:8})+'</td><td>'+money(h.cost_basis)+'</td><td>'+money(h.latest_nav)+'</td><td>'+escapeHtml(h.nav_date||"—")+'</td><td>'+money(h.market_value)+'</td><td class="'+(pnl==null?"":pnl>=0?"positive":"negative")+'">'+money(pnl)+'</td><td class="'+(h.nav_freshness==="FRESH"?"positive":"negative")+'">'+escapeHtml(h.nav_freshness)+'</td></tr>'}).join("")||'<tr><td colspan="8" class="muted">No holdings yet. Add a BUY transaction or import a statement.</td></tr>';
 renderPortfolioAllocation(d.holdings||[],Number(d.current_value)||0,d.missing_nav_scheme_codes||[]);
 $("importResult").textContent="Valuation status: "+d.valuation_status+"\nNAV freshness: "+d.valuation_freshness+"\nCurrent value: "+money(d.current_value)+"\nGross buys: "+money(d.gross_buy_amount)+"\nRealized proceeds: "+money(d.realized_proceeds)+(d.missing_nav_scheme_codes?.length?"\nMissing NAVs: "+d.missing_nav_scheme_codes.join(", "):"")+(d.stale_nav_scheme_codes?.length?"\nStale NAVs: "+d.stale_nav_scheme_codes.join(", "):"");
 const jobs=await Promise.allSettled([loadTransactions(),loadPortfolioRisk(),loadPortfolioReports(),loadPortfolioLookthrough()]);
 const targets=[["transactionMessage","Transaction history"],["portfolioRiskResult","Portfolio risk"],["portfolioReportHistory","Report history"],["lookthroughCoverage","Look-through"]];
 if(requestId!==portfolioViewRequest||id!==portfolioId())return null;
 jobs.forEach((result,index)=>{if(requestId!==portfolioViewRequest||id!==portfolioId())return;if(result.status==="rejected"){const [target,label]=targets[index];$(target).textContent=label+" unavailable: "+result.reason.message;if(index===1){$("portfolioRiskStatus").textContent="Unavailable";lastPortfolioRisk=null;lastPortfolioRiskPortfolioId=null}}});
 $("portfolioOverview").dataset.loadedPortfolioId=id;
 return d;
}
async function voidTransaction(transactionId){const reason=window.prompt("Enter a reason for voiding this transaction. The original ledger record will be preserved.");if(reason===null)return;if(reason.trim().length<3){$("transactionMessage").textContent="Void reason must contain at least three characters.";return}if(!window.confirm("Record an audited void for transaction #"+transactionId+"? This does not delete the original record."))return;try{await api("/v1/portfolios/"+portfolioId()+"/transactions/"+encodeURIComponent(transactionId)+"/void",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({reason:reason.trim()})});$("transactionMessage").textContent="Transaction #"+transactionId+" voided with an audit reason. The original record remains in history.";await loadPortfolio()}catch(e){$("transactionMessage").textContent=e.message;showError(e)}}
function updateTransactionAmount(){const units=Number($("transactionUnits").value),nav=Number($("transactionNav").value);if(Number.isFinite(units)&&units>0&&Number.isFinite(nav)&&nav>0)$("transactionAmount").value=(Math.round((units*nav+Number.EPSILON)*100)/100).toFixed(2);else $("transactionAmount").value=""}
async function saveTransaction(event){event.preventDefault();try{const id=portfolioId(),units=Number($("transactionUnits").value),nav=Number($("transactionNav").value);updateTransactionAmount();if(!Number.isInteger(Number($("transactionScheme").value))||Number($("transactionScheme").value)<=0)throw new Error("Enter a valid AMFI scheme code.");if(!units||!nav||!$("transactionAmount").value)throw new Error("Enter valid units and transaction NAV.");const payload={scheme_code:Number($("transactionScheme").value),transaction_type:$("transactionType").value,transaction_date:$("transactionDate").value,units:String(units),nav:String(nav),amount:$("transactionAmount").value,charges:(Number($("transactionCharges").value)||0).toFixed(2),notes:$("transactionNotes").value.trim()||null};if(!payload.transaction_date)throw new Error("Select the transaction date.");$("addTransaction").disabled=true;$("transactionMessage").textContent="Saving transaction and validating the running unit balance…";const result=await api("/v1/portfolios/"+id+"/transactions",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});$("transactionMessage").textContent="Transaction #"+result.id+" saved. The immutable ledger audit event was recorded.";const keepDate=$("transactionDate").value;$("transactionForm").reset();$("transactionDate").value=keepDate;$("transactionCharges").value="0";$("transactionAmount").value="";await loadPortfolio()}catch(e){$("transactionMessage").textContent=e.message;showError(e)}finally{$("addTransaction").disabled=false}}
let pendingImportCsv="",pendingImportToken="",pendingImportPortfolioId="";
async function previewStatement(){try{const file=$("statementFile").files[0];if(!file)throw new Error("Choose a CSV statement first.");if(file.size>1000000)throw new Error("Statement is larger than the 1 MB client safety limit.");pendingImportCsv=await file.text();pendingImportPortfolioId=portfolioId();const d=await api("/v1/portfolios/"+pendingImportPortfolioId+"/transactions/import/preview",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({csv_text:pendingImportCsv})});pendingImportToken=d.confirmation_token;$("confirmImport").disabled=false;$("importResult").textContent="PREVIEW READY · "+d.row_count+" rows\nBuy cash outflow: "+money(d.buy_cash_outflow)+"\nSell cash inflow: "+money(d.sell_cash_inflow)+"\nFingerprint: "+d.statement_sha256.slice(0,16)+"…\n\n"+d.rows.slice(0,25).map(r=>r.row_number+". "+r.scheme_name+" ("+r.scheme_code+") · "+r.transaction_type+" · "+r.units+" units @ "+r.nav+" · "+money(r.amount)).join("\n")+(d.rows.length>25?"\n…and "+(d.rows.length-25)+" more rows":"")+"\n\nReview the statement, then confirm within 10 minutes. No transactions have been written yet."}catch(e){pendingImportToken="";$("confirmImport").disabled=true;showError(e)}}
async function confirmStatementImport(){try{if(!pendingImportToken||!pendingImportCsv)throw new Error("Preview the statement first.");if(portfolioId()!==pendingImportPortfolioId)throw new Error("Portfolio changed after preview. Preview the statement again.");const d=await api("/v1/portfolios/"+pendingImportPortfolioId+"/transactions/import",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({csv_text:pendingImportCsv,confirmation_token:pendingImportToken})});$("importResult").textContent="Imported "+d.imported_count+" transactions.\nFingerprint: "+d.statement_sha256.slice(0,16)+"…\nRaw CSV was not stored.";pendingImportToken="";pendingImportCsv="";$("confirmImport").disabled=true;await loadPortfolio()}catch(e){showError(e)}}
function targetRows(){const rows=$("targets").value.trim().split(/\r?\n/).filter(Boolean);if(!rows.length)throw new Error("Enter one or more target rows.");const targets=rows.map((row,index)=>{const [code,pct]=row.split(",").map(x=>x.trim());if(index===0&&/scheme/i.test(code))return null;if(!/^\d+$/.test(code)||!/^\d+(\.\d+)?$/.test(pct))throw new Error("Target row "+(index+1)+" must be scheme_code,target_percent.");return {scheme_code:Number(code),target_percent:pct}}).filter(Boolean);if(!targets.length)throw new Error("Enter at least one target allocation.");return targets}
