async function loadGoals(){const d=await api("/v1/goals");renderGoals(d.items||[]);return d}
function renderGoals(goals){$("goalCount").textContent=goals.length+" saved";$("goalList").innerHTML=goals.map(goal=>'<div class="command-centre-card"><div><strong>'+escapeHtml(goal.name)+'</strong><div class="muted">Target '+money(goal.target_amount_today)+' in today&#39;s rupees · '+escapeHtml(goal.target_date)+'</div><div class="muted">Current '+money(goal.current_amount)+' · Monthly '+money(goal.monthly_contribution)+(goal.linked_portfolio_id?' · Linked portfolio #'+goal.linked_portfolio_id:' · Manual amount')+'</div></div><div class="toolbar"><button type="button" data-goal-project="'+goal.id+'">Projection</button><button type="button" data-goal-delete="'+goal.id+'">Delete</button></div></div>').join("")||'<div class="muted">No goals saved yet. Add a goal above to start planning.</div>';document.querySelectorAll("[data-goal-project]").forEach(button=>button.onclick=()=>loadGoalProjection(Number(button.dataset.goalProject)).catch(error=>{$("goalProjection").textContent=error.message}));document.querySelectorAll("[data-goal-delete]").forEach(button=>button.onclick=()=>deleteGoal(Number(button.dataset.goalDelete)).catch(error=>{$("goalProjection").textContent=error.message}))}
async function createGoal(event){event.preventDefault();const low=Number($("goalReturnLow").value),base=Number($("goalReturnBase").value),high=Number($("goalReturnHigh").value);if(!(low<=base&&base<=high))throw new Error("Return assumptions must satisfy low ≤ base ≤ high.");const payload={name:$("goalName").value.trim(),target_amount_today:$("goalTarget").value,target_date:$("goalDate").value,current_amount:$("goalCurrent").value||"0",linked_portfolio_id:$("goalPortfolio").value?Number($("goalPortfolio").value):null,monthly_contribution:$("goalMonthly").value||"0",inflation_rate:Number($("goalInflation").value)/100,annual_return_low:low/100,annual_return_base:base/100,annual_return_high:high/100};const result=await api("/v1/goals",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});await loadGoals();await loadGoalProjection(result.id);setAuthMessage("Goal saved to your private account.");}
async function loadGoalProjection(id){const d=await api("/v1/goals/"+id+"/projection");const p=d.projection,scenarios=p.scenarios;$("goalProjection").innerHTML='<div class="sectionhead"><h3>'+escapeHtml(d.goal_name)+' · Projection</h3><span class="pill">'+p.months_to_goal+' months</span></div><div class="stats"><div class="stat"><label>Target in today&#39;s rupees</label><strong>'+money(p.target_amount_today)+'</strong></div><div class="stat"><label>Inflation-adjusted target</label><strong>'+money(p.inflation_adjusted_target)+'</strong></div><div class="stat"><label>Current amount · '+(d.current_amount_source==="LINKED_PORTFOLIO_MARKET_VALUE"?"Linked portfolio":"Manual input")+'</label><strong>'+money(p.current_amount)+'</strong><div class="muted">Monthly contribution '+money(p.monthly_contribution)+'</div></div></div><div class="stats">'+["low","base","high"].map(key=>'<div class="stat"><label>'+key.toUpperCase()+' · '+pct(scenarios[key].annual_return_assumption)+'</label><strong>'+money(scenarios[key].projected_future_value)+'</strong><div class="muted">Required monthly: '+money(scenarios[key].required_monthly_contribution)+'</div><div class="muted">Shortfall: '+money(scenarios[key].projected_shortfall)+'</div></div>').join("")+'</div><p class="footnote">'+escapeHtml(p.methodology)+' '+(d.limitations||[]).map(escapeHtml).join(" ")+'</p>';return d}
