async function ensureAuthWorkspaceLoaded(userId){
 if(loadedAuthUserId===userId)return;
 if(authWorkspaceLoadPromise){
  try{await authWorkspaceLoadPromise}catch(_){}
  if(loadedAuthUserId===userId)return;
 }
 const loadPromise=(async()=>{
  await Promise.all([loadStatus(),loadFundFacets(),loadSchemes(true),loadPortfolios(),loadGoals()]);
  if(session?.user?.id===userId)loadedAuthUserId=userId;
 })();
 authWorkspaceLoadPromise=loadPromise;
 try{await loadPromise}
 finally{if(authWorkspaceLoadPromise===loadPromise)authWorkspaceLoadPromise=null}
}
